import react, { useState } from "react";

const Home = () => {

    // var age = Number(prompt("ENter your age: "))

    const [age, setAge] = useState()
    const [ans,setAns] = useState()

    const ce = () => {

        if (age >= 18) {
            setAns("Eligible for vote")
        } else {
            setAns("Not Eligible for vote")

        }
    }


    return (
        <>

            <input  type="number" placeholder="ENter your age: " onChange={(event)=>setAge(event.target.value)}/>
            <button onClick={ce}>Check Eligibility</button>

            <h1>{ans}</h1>

            {/* {age>=18?"Vote":"not eligible"} */}

        </>
    )
}

export default Home
